              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "ownership" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Private vs state/local government idleness"
            subtitle="Toggle year ?? membership rates from CPS public/private rows"
          >
            <div className="mb-3">
              <ToggleGroup
                label="Year"
                value={String(ownYear) as "2024" | "2025"}
