                  />
                  <YAxis
                    yAxisId="right"
                    orientation="right"
                    tick={{ fill: SLATE, fontSize: 11 }}
                    unit="%"
                    width={40}
                  />
                  <Tooltip />
                  <Legend />
                  <Bar
                    yAxisId="left"
                    dataKey="daysIdle"
                    name="Days idle"
                    fill={TEAL}
                    radius={[4, 4, 0, 0]}
                  />
                  <Bar
                    yAxisId="right"
                    dataKey="membershipPct"
                    name="Membership %"
                    fill={AMBER}
                    radius={[4, 4, 0, 0]}
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="2025 workers idled by sector"
            subtitle="Service-providing industries accounted for 98% of workers beginning stoppages"
          >
            <div className="h-[320px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={SECTOR_SHARE_2025}
                  layout="vertical"
                  margin={{ top: 4, right: 16, bottom: 4, left: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" horizontal={false} />
                  <XAxis
                    type="number"
                    tickFormatter={(v: number) => fmtK(v)}
                    tick={{ fill: SLATE, fontSize: 11 }}
                  />
                  <YAxis
                    type="category"
                    dataKey="label"
                    width={130}
                    tick={{ fill: NAVY, fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v) => fmtInt(Number(v ?? 0))}
                    labelFormatter={(l) => String(l)}
                  />
                  <Bar dataKey="workers" fill={INDIGO} radius={[0, 4, 4, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

