    if (band === "all") return INDUSTRY_CROSS_2024;
    return INDUSTRY_CROSS_2024.filter((r) => r.band === band);
  }, [band]);

  const scatterData = useMemo(
    () =>
      filtered.map((r) => ({
        ...r,
        x: r.coveragePct2025,
        y: metric === "days" ? r.daysIdle2024 : r.workers2024,
        z: Math.max(r.workers2024, 500),
