  const rankData = useMemo(() => {
    const key = metric === "days" ? "daysIdle2024" : "workers2024";
    return [...filtered]
      .sort((a, b) => b[key] - a[key])
      .map((r) => ({
        label: r.label,
        value: r[key],
        coverage: r.coveragePct2025,
        band: r.band,
      }));
  }, [filtered, metric]);

  const ownership = ownershipForYear(ownYear);

