            { id: "rank", label: "Rank" },
            { id: "timeline", label: "Timeline" },
            { id: "ownership", label: "Ownership" },
          ]}
        />
        <ToggleGroup
          label="Metric"
          value={metric}
          onChange={setMetric}
          options={[
            { id: "days", label: "Days idle" },
            { id: "workers", label: "Workers idled" },
          ]}
        />
        <ToggleGroup
